int main()
{
    int n, a, b, cnt=0;
    cin >> n;
    for(a=1; a<=n; a++)
    {
        for(b=a; b<=n; b++)
        {
            if(a*b%2==0) cnt++;
        }
    }
    cout << cnt <<endl;
    return 0;
}

#include <iostream>
using namespace std;

int main()
{
    int l, r, a, b, n, cnt = 0;
    cin >> l >> r;

    a = 1;
    while(a<=r)
    {
        b = a;
        while(b<=r)
        {
            n = a+b;
            if(n>=l && n<=r) cnt++;
            b *= 2;
        }
        a *= 2;
    }
    cout << cnt <<endl;
    return 0;
}
